local app=require("setup.app")local project=require("setup.project")local runner,opts local lines={}local err local fonts={}local logo local function log(msg)print(msg)for line in(tostring(msg).."\n"):gmatch("(.-)\n")do lines[#lines+1]=line end while#lines>14 do table.remove(lines,1)end end local function readAsset(name)return love.filesystem.read("setup/panel/"..name)end local function begin(projectDir)if runner and runner.server and not runner.finished then runner.server:stop()end lines={}err=nil opts.projectDir=projectDir local ok,res=pcall(app.start,opts,readAsset,log)if ok then runner=res else err=type(res)=="table"and res.message or tostring(res)log("Error: "..err)end end function love.load(args)love.window.setTitle("brainCloud Setup")fonts.title=love.graphics.newFont(22)fonts.body=love.graphics.newFont(14)logo=love.graphics.newImage("setup/panel/logo.png")opts=app.parse(args or{})if opts.help or opts.bad then log(app.USAGE)return end local dir=opts.projectDir or love.filesystem.getWorkingDirectory()begin(dir)end function love.update()if runner and not runner.finished then local ok,res=pcall(runner.poll)if not ok then err=type(res)=="table"and res.message or tostring(res)log("Error: "..err)runner.finished=true end end end function love.directorydropped(path)begin(path)end function love.keypressed(key)if key=="escape"then love.event.quit()elseif key=="o"and runner and runner.url and not runner.finished then app.openBrowser(runner.url())end end function love.draw()love.graphics.clear(0.06,0.1,0.14)love.graphics.setColor(1,1,1)local scale=40/logo:getHeight()love.graphics.draw(logo,24,18,0,scale,scale)love.graphics.setColor(0.55,0.65,0.72)love.graphics.setFont(fonts.body)love.graphics.print("Setup",24+logo:getWidth()*scale+12,30)love.graphics.setColor(0.9,0.93,0.95)local y=76 if runner then local hasMain=io.open(project.join(project.dirname(runner.output),"main.lua"),"r")if hasMain then hasMain:close()end love.graphics.print("Game folder: "..project.dirname(runner.output)..(hasMain and""or"   (no main.lua here - drop your game folder on this window)"),24,y)y=y+22 love.graphics.print("Config: "..project.basename(runner.output),24,y)y=y+30 end for _,line in ipairs(lines)do love.graphics.print(line,24,y)y=y+20 end y=y+10 love.graphics.setColor(0.55,0.65,0.72)if runner and runner.finished then love.graphics.print("Finished. Esc to close.",24,y)else love.graphics.print("O: reopen the browser    Esc: quit    Drop a folder here to switch games",24,y)end end
